    'extension_token_all_auth_types_tip' => 'Если включено, любой пользователь (локальный, LDAP или SSO) может разрешить TeamPass автоматически настроить расширение браузера с помощью персонального токена доступа. Если отключено, доступ по токену могут использовать только пользователи OAuth2/SSO.',
