    'health_cron_delayed_help' => 'Cron работает, но фоновые задачи не обрабатываются. Скорее всего, у пользователя веб-сервера нет прав на запись в storage/logs/, поэтому обработчик задач не может создать файл блокировки и прерывает работу. Найдите в журнале ошибок PHP сообщение «cannot create lock file» и дайте пользователю веб-сервера права на запись в storage/logs/. См. раздел документации о правах доступа к файлам.',
    'health_cron_error_help' => 'За последние 10 минут запуск cron не обнаружен. Убедитесь, что настроено задание cron, которое каждую минуту запускает app/sources/scheduler.php (страница «Задачи»). См. разделы документации о задачах и правах доступа к файлам.',
