    'restore_missing_sharekeys' => 'Восстановить отсутствующие ключи объектов',
    'restore_missing_sharekeys_tip' => 'Этот инструмент обнаруживает и заново создает отсутствующие ключи объектов (для элементов, пользовательских полей и файлов). Пользователи без ключа объекта видят объект, но не могут его расшифровать (значок перечеркнутого пароля). Анализ ничего не изменяет. При восстановлении сначала с помощью вашей учетной записи воссоздаются недостающие опорные ключи внутренней учетной записи TP, затем фоновая задача раздает недостающие ключи всем пользователям. Создаются только отсутствующие ключи — существующие никогда не изменяются. Личные элементы обрабатываются отдельно: их ключ восстанавливается только для владельца и никому не раздается.',
    'restore_missing_sharekeys_analyze' => 'Анализировать',
