    'restore_missing_sharekeys_found' => 'Обнаружены отсутствующие ключи объектов. Нажмите «Восстановить», чтобы создать их заново.',
    'restore_missing_sharekeys_unrecoverable_tip' => 'У некоторых объектов нет пригодного опорного ключа: ни внутренняя учетная запись TP, ни выбранная учетная запись не могут их расшифровать. Выберите ниже пользователя, который все еще может их открыть, и запустите восстановление снова либо попросите этого пользователя сохранить их повторно — ключи будут заново созданы для всех.',
    'restore_missing_sharekeys_task_exists' => 'Задача восстановления ключей объектов уже ожидает выполнения или выполняется. Дождитесь ее завершения.',
