    'microlearning_got_it' => 'Понятно — больше не показывать',
    'microlearning_mute_all' => 'Отключить все советы',
    'microlearning_tip_unique_password' => 'Используйте для каждой учетной записи свой пароль: если данные одного сайта утекут, остальные останутся в безопасности. Генератор создаст пароль одним щелчком.',
    'microlearning_tip_passphrase' => 'Длина важнее сложности: парольную фразу из нескольких случайных слов легче запомнить, и ее гораздо труднее взломать, чем «P@ssw0rd1».',
    'microlearning_tip_secure_share' => 'Никогда не отправляйте пароль по электронной почте или в чате — такие копии хранятся вечно. У одноразовой ссылки есть срок действия, и открыть ее можно только столько раз, сколько вы разрешите.',
    'microlearning_tip_what_is_mfa' => 'Многофакторная аутентификация (MFA) добавляет второй замок: даже если кто-то украдет ваш пароль, без вашего телефона он не сможет войти. Включите ее в профиле.',
    'microlearning_tip_reuse_risk' => 'Один пароль для разных сервисов — все равно что один ключ от дома, машины и офиса: потеряли его однажды — потеряли все. Панель мониторинга безопасности показывает, какие из ваших паролей используются повторно.',
    'microlearning_tip_phishing' => 'TeamPass никогда не попросит ваш пароль по электронной почте. Если сомневаетесь, не переходите по ссылке — откройте TeamPass из закладки.',
    'microlearning_tip_browser_extension' => 'Расширение браузера подставляет пароли только на нужном сайте — надежная защита от фишинговых страниц-двойников. Настройте его в профиле одним щелчком.',
    'microlearning_tip_breach_check' => 'Пароль может быть надежным — и при этом уже опубликованным: в базах утечек миллиарды записей. Время от времени проверяйте свои элементы на утечки.',
    'microlearning_tip_expiry' => 'Важные учетные данные следует менять по расписанию. Для папки можно задать период продления — элементы с истекшим сроком отмечаются на вашей панели мониторинга.',
    'microlearning_tip_lock_leaving' => 'Отходите от рабочего места? Заблокируйте сеанс (Win+L / Ctrl+Cmd+Q). Открытый менеджер паролей на экране без присмотра сводит на нет любую другую защиту.',
