    'tasks_max_drain_time_tip' => 'Сколько времени один запуск фонового обработчика продолжает запускать новые задачи. Когда время истекает, обработчик дожидается выполняющихся задач и завершается, оставляя остальные в очереди до следующего запуска. Увеличьте значение для больших хранилищ, где генерация ключей идет медленно, чтобы задачи, поставленные в очередь другими задачами (например, отправка уведомлений по электронной почте), тоже успевали обрабатываться. От 10 до 3600, по умолчанию 55.',
