    'licence_trial_offline_title' => 'Запросить пробный период с другого компьютера',
    'licence_trial_offline_intro' => 'Откройте ссылку ниже на компьютере с доступом в Интернет. Откроется страница на сервере лицензий: после вашего подтверждения она выполнит запрос, который не смог отправить этот сервер. Дополнительный шаг нужен потому, что сервер лицензий принимает этот запрос только методом POST, а по ссылке его отправить нельзя.',
    'licence_trial_offline_warning' => 'Ссылка содержит лицензионный ключ этого экземпляра. Храните ее в секрете: она идентифицирует вашу лицензию, и вставлять ее можно только на странице, которую она открывает.',
    'licence_trial_offline_contact_tip' => 'Сообщение будет отправлено на этот адрес, а ссылка в нем укажет его как контактный адрес пробного периода: на него сервер лицензий отправит подтверждение. Адрес должен принадлежать домену этого экземпляра:',
