    'licence_trial_offline_email_subject' => 'TEAMPASS — запрос пробного периода расширения браузера',
    'licence_trial_offline_email_body' => 'Здравствуйте!<br><br>Этот сервер TeamPass (<strong>#tp_fqdn#</strong>) не может связаться с сервером лицензий, поэтому не смог сам запросить пробный период расширения браузера.<br><br>Откройте ссылку ниже на компьютере с доступом в Интернет, затем подтвердите запрос на открывшейся странице:<br><br><a href="#tp_trial_link#">#tp_trial_link#</a><br><br>После этого на адрес <strong>#tp_contact_email#</strong> придет сообщение с подтверждением. Перейдите по ссылке из него, чтобы активировать 30-дневный пробный период.<br><br>Важно знать:<br>- пробный период предоставляется только один раз для каждого домена и продукта;<br>- если запросить новое сообщение с подтверждением, предыдущая ссылка перестанет работать.<br><br>Эта ссылка содержит лицензионный ключ вашего экземпляра. Не пересылайте ее.',
