    'role_allow_security_posture_fix' => 'Показывать кнопки «Исправить» раздела «Состояние безопасности»',
    'role_allow_security_posture_fix_tip' => 'Участники этой роли видят кнопку «Исправить самое срочное», значок гаечного ключа у каждого отмеченного элемента и ссылку «Исправить» в баннере-напоминании. Эти кнопки ведут только к элементам, которые пользователь может редактировать. Если флажок снят, они скрыты: пользователь по-прежнему видит раздел «Состояние безопасности» и сохраняет права на редактирование, полученные через папки. Пользователь получает эти кнопки, если их разрешает хотя бы одна из его ролей.',
