    'folder_contains_lapr_items' => 'Удаление заблокировано, так как выбранное дерево папок содержит элементы, связанные с LAPR. Переместите их за пределы этого дерева папок или сначала удалите связь с управляемой учетной записью или конечной точкой.',
    'folder_lapr_personal_move_blocked' => 'Эта папка содержит элементы, связанные с LAPR, и не может быть перемещена в личную папку. Сначала переместите элементы LAPR или отвяжите их.',
