    'lapr_endpoint_credential_unavailable' => 'Элемент с учетными данными SSH этой конечной точки был удален или перемещен в личную папку. Восстановите его или верните в общую папку, прежде чем восстанавливать конечную точку.',
    'restore_missing_sharekeys_source' => 'Открывать объекты с помощью ключей пользователя',
    'restore_missing_sharekeys_source_self' => 'Моя учетная запись',
    'restore_missing_sharekeys_source_keys_fmt' => 'Ключей общих элементов: %d',
    'restore_missing_sharekeys_source_tip' => 'Восстановление открывает каждый объект с помощью этих ключей, чтобы проверить и при необходимости пересоздать опорный ключ внутренней учетной записи TP. Выберите пользователя, который все еще может открыть объекты, недоступные вашей учетной записи, и введите его пароль: он используется только на сервере для открытия его ключей в рамках этого восстановления, не сохраняется и не отправляется обратно.',
    'restore_missing_sharekeys_source_pwd_required' => 'Введите пароль выбранного пользователя.',
    'restore_missing_sharekeys_source_refused' => 'Этот пароль не открывает ключи выбранного пользователя, либо эту учетную запись нельзя использовать для восстановления.',
    'restore_missing_sharekeys_tp_key_unavailable' => 'Не удается открыть ключ внутренней учетной записи TP на этом сервере, поэтому ни один объект нельзя проверить или восстановить. Убедитесь, что ключ экземпляра (TEAMPASS_SECRETS) — тот же, с которым создавалась эта база данных.',
