    'restore_missing_sharekeys_seed_replaced' => 'Объектов с опорным ключом, который больше их не открывал (остался после незавершенного распределения ключей): #replaced#. Ключ заменен, а ключи других пользователей для этих объектов пересоздаются фоновой задачей.',
    'webauthn_passkeys' => 'Ключи доступа',
