    'webauthn_delete' => 'Удалить ключ доступа',
    'webauthn_delete_confirm' => 'TeamPass больше не сможет входить на <b>#site#</b> с этим ключом доступа, но на сайте он останется зарегистрированным. Убедитесь, что у учетной записи есть другой способ входа, затем удалите ключ доступа и на сайте.',
    'webauthn_list_marker' => 'Содержит ключ доступа',
    'webauthn_password_replaced' => 'Ключ доступа — см. ниже',
    'webauthn_copy_not_copied' => 'Этот элемент содержит ключи доступа. Они не копируются: ключ доступа принадлежит только одному элементу.',
    'webauthn_provider_enabled' => 'Разрешить расширению браузера сохранять ключи доступа',
    'webauthn_provider_enabled_tip' => 'Расширение сохраняет ключи доступа сторонних сайтов в элементах и выполняет вход с их помощью. Все, кто может открыть элемент, могут использовать его ключи доступа, а каждое использование записывается в историю элемента. Требуется HTTPS.',
    'webauthn_email_on_add' => 'Уведомлять пользователей о сохранении ключа доступа',
    'webauthn_email_on_add_tip' => 'Отправляет письмо пользователю, сохранившему ключ доступа, чтобы добавление, сделанное без его ведома, не осталось незамеченным. Требуется почтовый сервер.',
    'email_subject_webauthn_credential_added' => '[TeamPass] В одну из ваших учетных записей добавлен ключ доступа',
    'email_body_webauthn_credential_added' => 'Здравствуйте,<br><br>Ключ доступа для вашей учетной записи <b>#rp_name#</b> (#user_name#) только что сохранен в TeamPass в элементе <a href="#link#">#item_label#</a> #tp_date# в #tp_time#.<br><br>Если это были не вы, откройте элемент в TeamPass, удалите незнакомый ключ доступа, удалите его также на сайте, сообщите администратору и немедленно смените пароль этой учетной записи.<br><br>С уважением',
    'email_tpl_webauthn_credential_added' => 'Ключ доступа сохранен',
    'email_tpl_webauthn_credential_added_desc' => 'Отправляется пользователю, сохранившему ключ доступа из расширения браузера, если включен соответствующий параметр в разделе Настройки > API > Расширение браузера.',
    'at_webauthn_credential_added' => 'Ключ доступа добавлен',
    'at_webauthn_credential_deleted' => 'Ключ доступа удален',
    'at_webauthn_credential_used' => 'Использован ключ доступа',
    'action_webauthn_used' => 'выполнен вход с ключом доступа для',
    'health_check_webauthn_http' => 'Ключи доступа по обычному HTTP',
    'health_check_webauthn_http_message' => 'Ключи доступа включены, но API по-прежнему принимает обычные HTTP-запросы: сеанс, с помощью которого TeamPass выполняет вход на сторонних сайтах, может быть перехвачен. Включите «Require HTTPS for API requests» в разделе Настройки > API.',
    'webauthn_login_passkeys' => 'Ключи доступа для входа',
    'webauthn_login_tip_disabled' => 'Ключи доступа больше не могут использоваться для входа в TeamPass: администратор отключил эту функцию. Вы можете удалить перечисленные ниже ключи.',
    'webauthn_login_tip_second_factor' => 'Ключ доступа (отпечаток пальца, лицо, PIN-код или аппаратный ключ безопасности) подтверждает вход вместо кода. После добавления ключа TeamPass будет запрашивать его после пароля при каждом входе.',
    'webauthn_login_tip_passwordless' => 'Ключ доступа (отпечаток пальца, лицо, PIN-код или аппаратный ключ безопасности) позволяет войти без пароля или подтверждает вход вместо кода. После добавления ключа TeamPass будет запрашивать его после пароля при каждом входе.',
    'webauthn_login_tip_directory' => 'Ключ доступа (отпечаток пальца, лицо, PIN-код или аппаратный ключ безопасности) подтверждает вход вместо кода. После добавления ключа TeamPass будет запрашивать его после пароля при каждом входе. Ваша учетная запись управляется каталогом, поэтому пароль требуется всегда.',
    'webauthn_login_label_placeholder' => 'Название этого устройства (необязательно)',
    'webauthn_login_add' => 'Добавить ключ доступа',
    'webauthn_login_none' => 'Ключей доступа пока нет.',
    'webauthn_login_passwordless_badge' => 'Без пароля',
