    'webauthn_login_passwordless_disable_confirm' => 'Этот ключ доступа будет подтверждать только те входы, при которых вводится пароль. TeamPass удалит хранящуюся у него копию вашего ключа шифрования.',
    'webauthn_login_added' => 'Ключ доступа добавлен.',
    'webauthn_login_passwordless_enabled' => 'Теперь этот ключ доступа позволяет входить без пароля.',
