    'webauthn_login_admin_delete_confirm' => 'Подтвердить удаление',
    'webauthn_login_mode' => 'Войти с ключом доступа',
    'webauthn_login_mode_tip' => 'Ничего не включается принудительно: у пользователей, добавивших ключ доступа в профиле, он запрашивается при каждом входе, остальные входят как прежде. В режиме второго фактора пароль по-прежнему вводится, а ключ доступа заменяет код. В режиме без пароля локальные учетные записи могут входить только с ключом доступа; учетные записи каталога и OAuth2 используют его как второй фактор.',
