    'webauthn_login_require_prf' => 'Требовать PRF для входа без пароля',
    'webauthn_login_require_prf_tip' => 'Ключ доступа, позволяющий входить без пароля, содержит копию ключа шифрования пользователя. При использовании расширения PRF открыть ее может только аутентификатор; без PRF (некоторые конфигурации Windows Hello) ее открывает секрет сервера. Включите этот параметр, чтобы запретить второй вариант: такие ключи доступа останутся вторыми факторами.',
    'webauthn_login_email_on_add_tip' => 'Отправляет пользователю письмо, когда в его учетную запись добавляется ключ доступа или он сохраняется расширением браузера. Также доступно в разделе Настройки > API > Расширение браузера.',
    'webauthn_rp_id' => 'Идентификатор проверяющей стороны',
    'webauthn_rp_id_tip' => 'Домен, к которому привязаны ключи доступа. Оставьте пустым, чтобы использовать хост из URL TeamPass; родительский домен также допускается. После изменения все зарегистрированные ключи доступа перестанут работать.',
    'webauthn_rp_name' => 'Название, отображаемое при создании ключа доступа',
    'webauthn_rp_name_tip' => 'Отображается браузером и аутентификатором. По умолчанию: TeamPass.',
    'email_subject_webauthn_login_added' => '[TeamPass] В вашу учетную запись TeamPass добавлен ключ доступа',
    'email_body_webauthn_login_added' => 'Здравствуйте,<br><br>Ключ доступа <b>#passkey_label#</b> был добавлен в вашу учетную запись TeamPass #tp_date# в #tp_time# с IP-адреса #tp_ip#.<br><br>Если это были не вы, немедленно удалите его в своем профиле в TeamPass (Ключи доступа для входа), смените пароль и сообщите администратору.<br><br>С уважением',
    'email_tpl_webauthn_login_added' => 'Добавлен ключ доступа для входа',
    'email_tpl_webauthn_login_added_desc' => 'Отправляется пользователю при добавлении ключа доступа в его учетную запись TeamPass, если включен соответствующий параметр.',
    'log_user_webauthn_added' => 'Добавлен ключ доступа для входа',
