    'webauthn_login_2fa_retry_passwordless' => 'Нажмите «Войти с ключом доступа», чтобы продолжить.',
    'webauthn_login_passwordless_not_enabled' => 'Этот ключ доступа не настроен для входа без пароля. Войдите с паролем, затем включите эту возможность в своем профиле.',
    'webauthn_login_passwordless_stale' => 'Этот ключ доступа больше не позволяет входить без пароля: ваши ключи шифрования изменились. Войдите с паролем, затем снова включите эту возможность в своем профиле.',
    'webauthn_login_prf_missing' => 'Этот браузер не может разблокировать ключ доступа для входа без пароля. Войдите с паролем.',
    'webauthn_login_passwordless_mfa_required' => 'Для вашей учетной записи требуется другой второй фактор: войдите с паролем.',
    'webauthn_login_passwordless_failed' => 'Вход с ключом доступа отклонен',
    'webauthn_passwordless_satisfies_mfa' => 'Вход без пароля засчитывается как MFA',
    'webauthn_passwordless_satisfies_mfa_tip' => 'Ключ доступа, проверяющий пользователя (PIN-код или биометрия), уже обеспечивает два фактора. Если параметр отключен, учетные записи, для которых обязательны Google или Duo, должны входить с паролем.',
    'admin_checklist_mfa_passkeys_only' => 'Ключи доступа — единственный способ MFA, и их использование не обязательно',
    'admin_checklist_mfa_passkeys_only_desc' => 'Учетная запись без ключа доступа для входа по-прежнему входит только с паролем. Включите другой метод MFA, чтобы сделать второй фактор обязательным.',
    'folders_show_more' => 'Показать больше папок',
