    'secure_send_audit_retention_invalid' => 'Введите целое число дней от 0 до 36500. Используйте 0, чтобы хранить все события аудита Secure Send.',
    'secure_send_audit_retention_days' => 'Срок хранения аудита Secure Send (дни)',
    'secure_send_audit_retention_hint' => '0 — хранить все события; иначе события хранятся от 1 до 36500 дней. Очистка выполняется вместе с задачей «Items integrity scan» на странице «Задачи», только если она запланирована, пакетами до 1000 записей.',
    'secure_send_audit_retention_warning' => 'Удаление необратимо и может сделать статистику неполной. Увеличение срока хранения не восстанавливает историю. Резервные копии и внешние журналы имеют собственные сроки хранения.',
    'secure_send_audit_retention_purge' => 'Очистка аудита Secure Send по сроку хранения',
    'secure_send_audit_retention_summary' => 'Удалено событий аудита: {deleted_count} (до {cutoff}); срок хранения: {retention_days} дн.; лимит пакета: {batch_limit}.',
    'password_policy_not_met' => 'Пароль не принят. Он должен содержать не менее 8 символов, заглавные и строчные буквы, а также цифру или специальный символ. Пароль должен отличаться от текущего и не может содержать ваш логин, имя или часть адреса электронной почты.',
    'expand_all' => 'Развернуть все',
