    'ops_secure_send_scope' => 'Только события за выбранный период. Личные фильтры и фильтры API к этой карточке не применяются. Служебные учетные записи TeamPass исключены.',
    'ops_secure_send_loading' => 'Загрузка активности Secure Send…',
    'ops_secure_send_unavailable' => 'Активность Secure Send недоступна. Обновите страницу, чтобы повторить; если проблема сохраняется, проверьте миграцию аудита и доступ к базе данных.',
    'ops_secure_send_disabled' => 'Secure Send сейчас отключен. Ранее записанная активность по-прежнему отображается.',
    'ops_secure_send_history' => 'Данные собираются после миграции аудита; более ранняя активность не восстанавливается. Удаление ссылок или учетных записей отправителей не стирает их записанную историю. Настроенный срок хранения аудита может удалить более старые события и сделать выбранный период неполным.',
    'ops_secure_send_interpretation' => 'Раскрытия отражают расшифровку на сервере, а не подтвержденное прочтение установленным получателем. Неудачные попытки относятся к получателям ссылок отправителя и сами по себе не доказывают злоупотреблений с его стороны. Автоматическая блокировка не применяется.',
