    'webauthn_login_stepup_title' => 'Подтвердите пароль',
    'webauthn_login_stepup_prompt' => 'В целях безопасности введите пароль, чтобы добавить ключ доступа или разрешить ему вход без пароля.',
    'webauthn_login_stepup_signin' => 'В целях безопасности войдите снова, прежде чем добавлять ключ доступа или разрешать ему вход без пароля.',
    'webauthn_login_stepup_failed' => 'Пароль для ключа доступа не подтвержден',
    'webauthn_login_passwordless_prf_required' => 'Этот ключ доступа больше не позволяет входить без пароля: администратор теперь требует PRF, который его аутентификатор не поддерживает. Войдите с паролем; ключ доступа по-прежнему подтверждает вход.',
    'webauthn_rp_id_invalid' => 'Идентификатор проверяющей стороны должен быть хостом из URL TeamPass (%s) или одним из его родительских доменов.',
    'webauthn_rp_id_change_confirm' => 'Ключей доступа для входа, зарегистрированных для #rp_id#: #count#. С новым значением они перестанут работать, и их владельцам придется зарегистрировать их заново. Продолжить?',
    'webauthn_login_require_prf_confirm' => 'Ключей доступа для входа, использующих копию ключа шифрования, которую открывает только сервер: #count#. Требование PRF навсегда удалит эти копии: такие ключи доступа смогут только подтверждать пароль, а повторное выключение этого параметра копии не вернет. Их владельцам придется снова включить вход без пароля в своем профиле. Продолжить?',
    'webauthn_login_https_required' => 'Для ключей доступа нужен HTTPS: браузеры отклоняют их на обычном HTTP-адресе, таком как URL TeamPass (%s). Настройте работу TeamPass по HTTPS, прежде чем включать их.',
    'webauthn_login_other_rp' => 'Зарегистрирован для %s: больше не работает',
    'webauthn_login_other_rp_tip' => 'Идентификатор проверяющей стороны изменился после регистрации этого ключа доступа: он больше не может использоваться для входа. Удалите его и добавьте новый.',
    'webauthn_login_orphaned_passkeys' => 'Ключей доступа для входа, зарегистрированных для другого идентификатора проверяющей стороны: %d. Они больше не могут использоваться для входа: у их владельцев они не запрашиваются и отображаются в профиле с пометкой, где их можно удалить.',
    'webauthn_login_unknown_passkey' => 'Этот ключ доступа больше не зарегистрирован в TeamPass. Удалите его со своего устройства или из менеджера паролей, затем войдите с паролем.',
    'webauthn_login_notice_not_asked' => 'TeamPass не запрашивает ключ доступа после пароля: многофакторная аутентификация отключена для вашей учетной записи. Попросите администратора включить ее.',
    'webauthn_login_notice_single_device' => 'Ваш единственный ключ доступа остается на устройстве, которое его создало. Добавьте второй — на телефоне или аппаратном ключе безопасности, — чтобы входить, когда это устройство недоступно.',
